@extends('layouts.app') @section('title','پیگیری سفارش | تیشه') @section('content')<div class="container page"><div class="section-heading"><div><span class="eyebrow">سفارش مستقیم مصالح</span><h1 class="page-title">پیگیری سفارش #{{ \App\Support\Format::number($order->id) }}</h1></div><span class="tag {{ $order->status }}">{{ \App\Support\Format::status($order->status) }}</span></div><div class="notice">شماره پیگیری سفارش (نه شماره تراکنش بانکی): <b class="order-reference" dir="ltr">{{ $order->reference }}</b><br>روش: پرداخت مستقیم بین طرفین · وضعیت پرداخت: خارج از سامانه و تأییدنشده</div>@if($order->reservation_expires_at&&$order->status==='awaiting_seller')<p class="notice">مهلت پاسخ فروشنده: {{ \App\Support\Format::date($order->reservation_expires_at) }}، {{ $order->reservation_expires_at->format('H:i') }} UTC. پس از پایان مهلت و اجرای زمان‌بندی، سفارش لغو و موجودی آزاد می‌شود.</p>@endif @if($order->quote_acceptance_required&&$order->status==='confirmed')<section class="panel"><h2>تغییر مبلغ نهایی؛ نیازمند پذیرش خریدار</h2><p>فروشنده هزینه حمل نهایی را تعیین یا تغییر داده است. مبلغ جدید: <strong class="gold">{{ \App\Support\Format::money($order->total) }}</strong>. آماده‌سازی و درگاه دمو تا پذیرش خریدار مجاز نیست.</p>@if(auth()->id()===$order->buyer_id&&$order->status==='confirmed')<form method="post" action="{{ route('orders.accept-quote',$order) }}">@csrf<input type="hidden" name="expected_total" value="{{ $order->total }}"><button class="button">مبلغ نهایی جدید را می‌پذیرم</button></form><small>این پذیرش پرداخت نیست؛ در صورت عدم توافق از بخش تغییر وضعیت سفارش را لغو کنید.</small>@endif</section>@endif<div class="detail-grid"><section><div class="panel"><h2>اقلام و مبلغ اعلامی</h2>@foreach($order->items as $item)<div class="list-row"><div><h3>{{ $item->name }}</h3><small>{{ $item->brand }} · {{ \App\Support\Format::number($item->quantity) }} {{ config('tisheh.units.'.$item->unit) }}</small></div><strong class="gold">{{ \App\Support\Format::money($item->line_tota